import java.util.ArrayList;
import java.util.List;

class Solution {
    public int[][] merge(int[][] intervals) {
        List<int[]> merged = new ArrayList<>();
        for (int[] interval : intervals) {
            int start = interval[0];
            int end = interval[1];
            int index = 0;
            while (index < merged.size() && merged.get(index)[1] < start) {
                index++;
            }
            while (index < merged.size() && merged.get(index)[0] <= end) {
                int[] current = merged.remove(index);
                start = Math.min(start, current[0]);
                end = Math.max(end, current[1]);
            }
            merged.add(index, new int[] {start, end});
        }
        return merged.toArray(new int[merged.size()][]);
    }
}

